361			}
362		}
363		// man pages: foo.1 .. foo.9, plus pre-rendered roff variants.
364		if strings.HasSuffix(lower, ".prebuilt") || strings.HasSuffix(lower, ".roff") || strings.HasSuffix(lower, ".man") {
