   548			if tail[index] != '=' {
   549				continue
   550			}
   551			// Skip the comparison operators: `==`, `!=`, `<=`, `>=`.
   552			if index+1 < len(tail) && tail[index+1] == '=' {
   553				index++
   554				continue
   555			}
   556			if index > 0 && strings.IndexByte("=!<>", tail[index-1]) >= 0 {
   557				continue
   558			}
   559			rest := strings.TrimSpace(strings.TrimRight(strings.TrimSpace(tail[index+1:]), ";"))
   560			switch rest {
   561			case "", "0", "delete", "default":
   562				return false
   563			}
   564			return true
   565		}
   566		return false
