441	// asking whether the query's final word happens to end in a plural.
442	//
443	// The final-word test read `what are we doing about deployments` — a singular question about one
444	// activity — as a request for a list, because its last word is a plural noun in a prepositional
445	// phrase that is not the grammatical head at all. Sacrificing baseline head slots on that reading
446	// is a silent ranking change the caller never asked for.
447	//
448	// The frame allows a determiner and a modifier or two before the head (`what are the open
449	// questions`, `what are the remaining blockers`) and stops at a personal pronoun, which is the
450	// marker that the sentence continued into a verb phrase rather than naming a set.
451	func proseArePluralFrame(written []string, areIndex int) bool {
452		const frameWidth = 3
453		for offset := 1; offset <= frameWidth; offset++ {
454			index := areIndex + offset
455			if index >= len(written) {
456				return false
457			}
458			word := written[index]
459			if safeASCIIWrittenPlural(word) {
460				return true
461			}
462			if prosePronoun(word) {
463				return false
464			}
465		}
466		return false
467	}
468	
