  1	package sem
  2	
  3	import (
  4		"fmt"
  5		"strings"
  6		"testing"
  7	)
  8	
  9	// A snapshot or golden file is a machine-written recording of expected output. It belongs in the
 10	// section that carries its name — docs-and-fixtures — and not in the PRIMARY list an agent reads as
 11	// its set of candidate fix sites, where it also anchors related-site expansion on a neighbourhood
 12	// that is not the change's.
 13	func TestSearchDocsSectionClaimsFixtureArtifacts(t *testing.T) {
 14		t.Parallel()
 15		q := buildSearchQuery("rule SIM201 reports the wrong message")
 16		for _, path := range []string{
 17			"crates/ruff/src/snapshots/rules__SIM201.py.snap",
 18			"internal/pkg/testdata/report.golden",
 19			"tests/__snapshots__/render.ambr",
 20		} {
 21			if !searchDocsSectionPath(q, path) {
 22				t.Fatalf("%s was left in the primary fix-site list", path)
 23			}
 24		}
 25		// Asking for the artifact keeps it primary, exactly as every other class prior behaves.
 26		if searchDocsSectionPath(buildSearchQuery("update the snapshot"), "tests/__snapshots__/render.ambr") {
 27			t.Fatal("a query that asked for snapshots had its snapshot labelled away")
 28		}
 29		// A real source file is untouched.
 30		if searchDocsSectionPath(q, "crates/ruff/src/rules/ast_unary_op.rs") {
 31			t.Fatal("a source file was labelled into docs-and-fixtures")
 32		}
 33	}
 34	
 35	// "expected X, got Y" is the most common sentence in a bug report. Treating "expected" as a request
 36	// FOR fixtures switched the fixture prior off on exactly the ordinary defect queries it exists to
 37	// correct, so snapshots kept full strength and could outrank the implementation again.
 38	func TestSearchFixturePriorSurvivesTheWordExpected(t *testing.T) {
 39		t.Parallel()
 40		path := "tests/__snapshots__/render.ambr"
 41		bug := buildSearchQuery("expected a 200 response but the handler returns 500")
 42		if prior := searchFileClassPrior(bug, path); prior != searchSecondaryClassPrior {
 43			t.Fatalf("fixture prior on a bug query = %v, want %v", prior, searchSecondaryClassPrior)
 44		}
 45		// Naming the artifact still switches the prior off.
 46		asked := buildSearchQuery("regenerate the snapshot for the renderer")
 47		if prior := searchFileClassPrior(asked, path); prior != 1 {
 48			t.Fatalf("fixture prior when the query asked for snapshots = %v, want 1", prior)
 49		}
 50	}
 51	
 52	// The prose basenames are matched as a PREFIX, and a prefix of a filename is not a filename:
 53	// `license_check.go`, `history_store.py` and `readme_parser.ts` are ordinary executable sources.
 54	// Classifying them as documentation halved their score AND — because NonProgramTextPath consumes
 55	// the same classification — declared them unable to hold a relation.
 56	func TestSearchDocClassLeavesSourceNamedLikeProseAlone(t *testing.T) {
 57		t.Parallel()
 58		for _, path := range []string{
 59			"internal/policy/license_check.go",
 60			"app/store/history_store.py",
 61			"src/docs-tools/readme_parser.ts",
 62			"cmd/newsfeed.go",
 63			"pkg/authors_index.rb",
 64		} {
 65			if class := classifySearchFile(path); class != searchFileClassSource {
 66				t.Fatalf("%s classified as %q, want source", path, class)
 67			}
 68			if NonProgramTextPath(path) {
 69				t.Fatalf("%s was declared non-program-text, so its relations were discarded", path)
 70			}
 71		}
 72		// The files the rule was written for keep their classification.
 73		for _, path := range []string{
 74			"README", "LICENSE", "LICENSE-APACHE", "COPYING", "AUTHORS", "NEWS",
 75			"README.md", "CHANGELOG.md", "docs/guide.rst",
 76		} {
 77			if class := classifySearchFile(path); class != searchFileClassDoc {
 78				t.Fatalf("%s classified as %q, want doc", path, class)
 79			}
 80		}
 81	}
 82	
 83	// A callable that opens no block is a declaration only when it has no body at all. Kotlin and C#
 84	// write executable bodies as expressions, and demoting those by the reference-declaration prior
 85	// pushes the real fix site down the ranking.
 86	func TestSearchReferenceDeclarationKeepsExpressionBodies(t *testing.T) {
 87		t.Parallel()
 88		callable := func(snippet string) SearchResult {
 89			return SearchResult{
 90				Kind: "function", Snippet: snippet,
 91				SymbolStartLine: 10, SymbolEndLine: 10,
 92				SnippetStartLine: 10, SnippetEndLine: 10,
 93			}
 94		}
 95		for _, snippet := range []string{
 96			"    fun formatAmount(value: Int) = value.toString()",
 97			"    public int Area() => Width * Height;",
 98			"    fun retries(limit: Int = 3) = limit * 2",
 99			"  def total: Int = items.sum",
100		} {
101			if searchReferenceDeclaration(callable(snippet)) {
102				t.Fatalf("expression body demoted as a reference declaration: %q", snippet)
103			}
104		}
105		// Real declarations are unchanged, including the C++ special members and a default argument.
106		for _, snippet := range []string{
107			"    virtual void flush() = 0;",
108			"    Buffer(const Buffer &) = delete;",
109			"    public function previous($fallback = false);",
110			"void redisSetCpuAffinity(const char *cpulist);",
111		} {
112			if !searchReferenceDeclaration(callable(snippet)) {
113				t.Fatalf("declaration lost its prior: %q", snippet)
114			}
115		}
116	}
117	
118	// `other than` is a list cue only as the ordered adjacent phrase. Testing the two words
119	// independently read a singular comparison as a request for many parents and cut the protected
120	// baseline head from half of top-k to a third.

