package sem

import "testing"

func TestTrail161ReviewDocNamedDataArtifactKeepsExplicitIntent(t *testing.T) {
	for _, path := range []string{"README.json", "CHANGELOG.xml"} {
		if got := searchFileClassPrior(buildSearchQuery("update the README changelog"), path); got != 1 {
			t.Fatalf("prior for explicitly requested %s = %v, want 1", path, got)
		}
	}
}

func TestTrail161ReviewExpectedOutputKeepsFixtureIntent(t *testing.T) {
	const path = "tests/testdata/parser.expected"
	if got := searchFileClassPrior(buildSearchQuery("update the expected output for the parser"), path); got != 1 {
		t.Fatalf("prior for explicitly requested expected output = %v, want 1", got)
	}
}

func TestTrail161ReviewAnnotatedDeclarationIsNotAnExpressionBody(t *testing.T) {
	result := SearchResult{
		Kind: "function", Snippet: `@JvmName("f") fun f(x: Int = 3);`,
		SymbolStartLine: 10, SymbolEndLine: 10,
		SnippetStartLine: 10, SnippetEndLine: 10,
	}
	if !searchReferenceDeclaration(result) {
		t.Fatal("annotated declaration was treated as an expression-bodied implementation")
	}
}

func TestTrail161ReviewLongPluralFrameRequestsMultipleParents(t *testing.T) {
	q := buildSearchQuery("what are the currently known open blockers")
	if got, want := proseParentHeadCount(q, 12), 4; got != want {
		t.Fatalf("head count = %d, want %d", got, want)
	}
}

