514			response, err := SearchRepository(t.Context(), repo, "test", query, SearchOptions{
515				Worktree: true, Profile: ProfileFast, TopK: 20, MaxIndexedFiles: 64,
516				MaxContextBytes: ceiling,
517			})
518			if err != nil {
519				t.Fatalf("%q: %v", query, err)
520			}
521			if err := response.Validate(); err != nil {
522				t.Fatalf("%q: the widened intent overshot its own validator: %v", query, err)
523			}
