530		// The artifact request must actually reach the primary list, or the budget above was
531		// measured on a payload the change never touched.
532		response, err := SearchRepository(t.Context(), repo, "test",
533			"update the expected output for the ledger renderer", SearchOptions{
534				Worktree: true, Profile: ProfileFast, TopK: 20, MaxIndexedFiles: 64,
535				MaxContextBytes: ceiling,
536			})
