541		for _, result := range response.Results {
542			if strings.HasSuffix(result.FilePath, ".ambr") && result.Section != SearchSectionDocs {
543				primary++
544			}
545		}
546		if primary == 0 {
547			t.Fatal("the requested expected-output artifact was demoted out of the primary list")
548		}
549	}

