   568	// searchExpressionBodiedCallable reports whether a braceless callable carries an EXPRESSION body.
   569	//
   570	// `=>` is unambiguous. A bare `=` is the Kotlin/Scala form, and it is read as an implementation
   571	// unless what follows is one of the three C++ special-member forms that assign no expression at
   572	// all: `= 0` (pure virtual), `= delete` and `= default`. Those remain declarations.
   573	//
   574	// The bias is deliberate. Treating an implementation as a declaration DEMOTES a fix site out of
   575	// the ranking; treating a declaration as an implementation merely leaves it at full weight, where
   576	// it competes on its score like anything else.
   577	func searchExpressionBodiedCallable(body string) bool {
   578		// What the scan looks for is an ASSIGNMENT IN THE CALLABLE'S TAIL: an `=` or `=>` that stands
   579		// OUTSIDE every parenthesised group and after the callable's parentheses have closed. Both
   580		// halves are load-bearing, and each excludes a different `=` that is not a body.
   581		//
   582		// DEPTH excludes every bracketed `=`. A DEFAULT ARGUMENT is one — `public function
   583		// previous($fallback = false);` is a PHP interface method and nothing else — and so is an
   584		// ANNOTATION or ATTRIBUTE argument, which is why the FIRST parenthesised group cannot simply be
   585		// skipped as the parameter list: in `@JvmName("f") fun f(x: Int = 3);` the first group belongs
   586		// to the annotation, and skipping it left the default argument in the scanned tail and read the
   587		// declaration as an expression body. Reading depth instead does not care which group is which.
   588		//
   589		// POSITION excludes an `=` written before any parentheses at all, which is where a GENERIC TYPE
   590		// PARAMETER writes its default: `template <class T = int> void reset();` and TypeScript's
   591		// `function f<T = string>(x: T): void;` are declarations. An expression body always follows the
   592		// parameter list, so requiring one closed group costs it nothing — `const f = (x: number) => x`
   593		// is still caught by the `=>` after that group. A callable written without parentheses at all
   594		// (Scala's `def f: Int = 42`) has no group to wait for and is scanned whole.
   595		depth := 0
   596		closedGroup := !strings.ContainsRune(body, '(')
   597		for index := 0; index < len(body); index++ {
   598			switch body[index] {
   599			case '(':
   600				depth++
   601				continue
   602			case ')':
   603				if depth > 0 {
   604					depth--
   605					closedGroup = closedGroup || depth == 0
   606				}
   607				continue
   608			case '=':
   609			default:
   610				continue
   611			}
   612			if depth > 0 || !closedGroup {
   613				continue
   614			}
   615			// Skip the comparison operators: `==`, `!=`, `<=`, `>=`.
   616			if index > 0 && strings.IndexByte("=!<>", body[index-1]) >= 0 {
   617				continue
   618			}
   619			if index+1 < len(body) && body[index+1] == '>' {
   620				return true
   621			}
   622			if index+1 < len(body) && body[index+1] == '=' {
   623				index++
   624				continue
   625			}
   626			rest := strings.TrimSpace(strings.TrimRight(strings.TrimSpace(body[index+1:]), ";"))
   627			switch rest {
   628			case "", "0", "delete", "default":
   629				return false
   630			}
   631			return true
   632		}
   633		return false
   634	}
